1: <!DOCTYPE html>
2: <html lang="en">
3: <head>
4: <meta charset="utf-8">
5: <meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">
6: <meta name="theme-color" content="#0d0f1a">
7: <title>Ring Rise</title>
8: <style>
9: html,body{margin:0;height:100%;background:#0d0f1a;overflow:hidden;overscroll-behavior:none;touch-action:none;-webkit-user-select:none;user-select:none;-webkit-tap-highlight-color:transparent}
10: canvas{position:fixed;left:0;top:0;display:block;touch-action:none}
11: </style>
12: </head>
13: <body>
14: <canvas id="c"></canvas>
15: <script>
16: (()=>{
17: 'use strict';
18: const cv=document.getElementById('c'),ctx=cv.getContext('2d');
19: // palette: dark bg + mint, pink, gold (+ off-white text)
20: const BG='#0d0f1a',MINT='#3de0c6',PINK='#ff4f78',GOLD='#ffd447',INK='#f4f6ff';
21: const LW=360,R=60,TH=11,BR=8,BX=LW/2,GAP=230,SPACE=2*R+GAP,PI=Math.PI,ZONE=BR+TH/2;
22: let H=640,sc=1,ox=0,dpr=1,BY=474;
23: let state='ready',score=0,best=0,spawned=0,speed=0,t=0,shake=0,pulse=0,overAt=0,newBest=false,muted=false,last=0;
24: let rings=[],stars=[],parts=[];
25: 
26: function ls(k,v){try{if(v===undefined)return localStorage.getItem(k);localStorage.setItem(k,v);}catch(e){return null;}}
27: best=parseInt(ls('rr_best'),10)||0;
28: muted=ls('rr_mute')==='1';
29: 
30: /* ---------- audio ---------- */
31: let ac=null;
32: function audio(){
33:   if(!ac){try{ac=new(window.AudioContext||window.webkitAudioContext)();}catch(e){ac=null;}}
34:   if(ac&&ac.state==='suspended')ac.resume();
35: }
36: function tone(f1,f2,dur,type,vol,delay){
37:   if(muted||!ac)return;
38:   const t0=ac.currentTime+(delay||0),o=ac.createOscillator(),g=ac.createGain();
39:   o.type=type||'sine';
40:   o.frequency.setValueAtTime(f1,t0);
41:   o.frequency.exponentialRampToValueAtTime(f2,t0+dur);
42:   g.gain.setValueAtTime(vol||.12,t0);
43:   g.gain.exponentialRampToValueAtTime(0.001,t0+dur);
44:   o.connect(g);g.connect(ac.destination);
45:   o.start(t0);o.stop(t0+dur+.03);
46: }
47: 
48: /* ---------- setup ---------- */
49: function resize(){
50:   const w=innerWidth,h=innerHeight;
51:   dpr=Math.min(window.devicePixelRatio||1,2);
52:   cv.width=Math.round(w*dpr);cv.height=Math.round(h*dpr);
53:   cv.style.width=w+'px';cv.style.height=h+'px';
54:   const gw=Math.min(w,h*0.62);          // portrait column, centred on wide screens
55:   sc=gw/LW;ox=(w-gw)/2;H=h/sc;BY=H*0.74;
56:   if(state==='ready'||!rings.length)reset();
57: }
58: function makeRing(y){
59:   const L=Math.min(Math.max(spawned-2,0),45);spawned++;   // difficulty level
60:   const om=(0.9+L*0.02)*(0.85+Math.random()*0.3);        // spin speed
61:   return{y:y,ph:Math.random()*PI*2,w:om*(Math.random()<.5?-1:1),gh:0.88-L*0.0058,st:0,fl:0};
62: }
63: function fill(){
64:   let top=rings.length?rings[rings.length-1].y:BY-430+SPACE;
65:   while(top>-(R+30)){top-=SPACE;rings.push(makeRing(top));}
66: }
67: function reset(){
68:   score=0;spawned=0;rings=[];parts=[];shake=0;pulse=0;newBest=false;speed=0;
69:   fill();
70: }
71: for(let i=0;i<34;i++)stars.push({x:Math.random()*LW,y:Math.random()*1100,k:.12+Math.random()*.3,s:1+Math.random()*1.6});
72: 
73: function burst(x,y,col,n){
74:   for(let i=0;i<n;i++){
75:     const a=Math.random()*PI*2,s=60+Math.random()*220;
76:     parts.push({x:x,y:y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,l:1,c:col});
77:   }
78: }
79: function die(){
80:   state='over';overAt=performance.now();shake=.35;
81:   if(score>best){best=score;newBest=true;ls('rr_best',String(best));}
82:   burst(BX,BY,GOLD,22);
83:   tone(320,45,.5,'sawtooth',.18);
84: }
85: 
86: /* ---------- input ---------- */
87: function flip(){
88:   const r=rings.find(q=>q.st===0);
89:   if(!r)return;
90:   r.w=-r.w;r.fl=1;
91:   tone(280,430,.06,'square',.06);
92: }
93: function act(){
94:   if(state==='ready'){state='play';}
95:   else if(state==='play'){flip();}
96:   else if(state==='over'){if(performance.now()-overAt>450){reset();state='play';}}
97:   else if(state==='paused'){state='play';last=performance.now();}
98: }
99: cv.addEventListener('pointerdown',e=>{
100:   e.preventDefault();audio();
101:   const x=(e.clientX-ox)/sc,y=e.clientY/sc;
102:   if(Math.hypot(x-(LW-30),y-34)<28){
103:     muted=!muted;ls('rr_mute',muted?'1':'0');
104:     if(!muted)tone(600,900,.08,'triangle',.1);
105:     return;
106:   }
107:   act();
108: },{passive:false});
109: document.addEventListener('touchmove',e=>e.preventDefault(),{passive:false});
110: document.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();audio();act();}});
111: function pause(){if(state==='play')state='paused';}
112: document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});
113: window.addEventListener('blur',pause);
114: window.addEventListener('pagehide',pause);
115: window.addEventListener('resize',resize);
116: window.addEventListener('orientationchange',()=>setTimeout(resize,150));
117: 
118: /* ---------- update ---------- */
119: function update(dt){
120:   if(state==='paused')return;
121:   t+=dt;
122:   if(state==='play')speed=235+Math.min(score,45)*3.2;      // ramps 235 -> ~380
123:   for(const s of stars){
124:     s.y+=(state==='play'?speed:24)*s.k*dt;
125:     if(s.y>H+4){s.y=-Math.random()*40;s.x=Math.random()*LW;}
126:   }
127:   for(const p of parts){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.98;p.vy*=.98;p.l-=dt*1.8;}
128:   parts=parts.filter(p=>p.l>0);
129:   shake=Math.max(0,shake-dt);pulse=Math.max(0,pulse-dt*4);
130:   for(const r of rings){
131:     if(state!=='over')r.ph+=r.w*dt;
132:     r.fl=Math.max(0,r.fl-dt*5);
133:   }
134:   if(state!=='play')return;
135: 
136:   for(const r of rings)r.y+=speed*dt;
137:   for(const r of rings){
138:     if(r.st===0&&r.y+R>BY-ZONE)r.st=1;                       // ball reaches ring
139:     if(r.st===1&&r.y-R>BY+ZONE){                             // ball cleared ring
140:       r.st=2;score++;pulse=1;
141:       const f=540+Math.min(score,24)*16;
142:       tone(f,f*1.5,.12,'triangle',.16);
143:       burst(BX,BY,MINT,6);
144:     }
145:   }
146:   for(const r of rings){
147:     if(r.st===2)continue;
148:     const dy=BY-r.y,d=Math.abs(dy);
149:     if(Math.abs(d-R)<ZONE-1){
150:       const a=dy>0?PI/2:-PI/2;
151:       let m=(a-r.ph)%PI;if(m<0)m+=PI;
152:       m=Math.min(m,PI-m);                                    // distance to nearest gap centre
153:       if(m>r.gh-0.1){die();return;}
154:     }
155:   }
156:   while(rings.length&&rings[0].y-R>H+40)rings.shift();
157:   fill();
158: }
159: 
160: /* ---------- drawing ---------- */
161: function txt(s,x,y,size,col,al,a){
162:   ctx.font='800 '+size+'px system-ui,-apple-system,"Segoe UI",Roboto,sans-serif';
163:   ctx.textAlign=al||'center';ctx.textBaseline='middle';
164:   ctx.globalAlpha=a===undefined?1:a;ctx.fillStyle=col;
165:   ctx.fillText(s,x,y);ctx.globalAlpha=1;
166: }
167: function rr(x,y,w,h,r){
168:   ctx.beginPath();ctx.moveTo(x+r,y);
169:   ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);
170:   ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath();
171: }
172: function arrow(r){
173:   const cx=BX,cy=r.y,dir=r.w>0?1:-1,a0=r.ph+.5,ae=a0+dir*1.7,ar=24;
174:   ctx.strokeStyle=PINK;ctx.fillStyle=PINK;ctx.lineWidth=4;ctx.lineCap='round';
175:   ctx.beginPath();ctx.arc(cx,cy,ar,a0,ae,dir<0);ctx.stroke();
176:   const px=cx+Math.cos(ae)*ar,py=cy+Math.sin(ae)*ar;
177:   const tx=-Math.sin(ae)*dir,ty=Math.cos(ae)*dir,nx=-ty,ny=tx;
178:   ctx.beginPath();
179:   ctx.moveTo(px+tx*9,py+ty*9);ctx.lineTo(px+nx*6,py+ny*6);ctx.lineTo(px-nx*6,py-ny*6);
180:   ctx.closePath();ctx.fill();
181: }
182: function drawRing(r,target){
183:   if(r.y<-R-30||r.y>H+R+30)return;
184:   const cap=(TH/2)/R;
185:   ctx.lineWidth=TH+r.fl*5;ctx.lineCap='round';
186:   ctx.strokeStyle=target?PINK:MINT;
187:   ctx.globalAlpha=target?1:(r.st===2?.25:(r.st===1?.9:.6));
188:   for(let k=0;k<2;k++){
189:     ctx.beginPath();
190:     ctx.arc(BX,r.y,R,r.ph+k*PI+r.gh+cap,r.ph+(k+1)*PI-r.gh-cap);
191:     ctx.stroke();
192:   }
193:   ctx.globalAlpha=1;
194:   if(target)arrow(r);
195: }
196: function drawBall(){
197:   ctx.fillStyle=GOLD;
198:   if(state==='play'){
199:     for(let i=5;i>=1;i--){
200:       ctx.globalAlpha=.07*(6-i);
201:       ctx.beginPath();ctx.arc(BX,BY+i*9,BR*(1-i*.1),0,7);ctx.fill();
202:     }
203:   }
204:   ctx.globalAlpha=.18;
205:   ctx.beginPath();ctx.arc(BX,BY,BR*2.1+pulse*6,0,7);ctx.fill();
206:   ctx.globalAlpha=1;
207:   const b=Math.sin(t*9)*.09;
208:   ctx.beginPath();ctx.ellipse(BX,BY,BR*(1+b+pulse*.2),BR*(1-b+pulse*.2),0,0,7);ctx.fill();
209: }
210: function drawMute(){
211:   ctx.save();ctx.translate(LW-30,34);
212:   ctx.globalAlpha=.8;ctx.fillStyle=INK;ctx.strokeStyle=INK;ctx.lineWidth=2.5;ctx.lineCap='round';
213:   ctx.beginPath();
214:   ctx.moveTo(-9,-4);ctx.lineTo(-4,-4);ctx.lineTo(2,-9);ctx.lineTo(2,9);ctx.lineTo(-4,4);ctx.lineTo(-9,4);
215:   ctx.closePath();ctx.fill();
216:   if(muted){
217:     ctx.beginPath();ctx.moveTo(6,-5);ctx.lineTo(14,5);ctx.moveTo(14,-5);ctx.lineTo(6,5);ctx.stroke();
218:   }else{
219:     ctx.beginPath();ctx.arc(2,0,7,-.9,.9);ctx.stroke();
220:     ctx.beginPath();ctx.arc(2,0,12,-.9,.9);ctx.stroke();
221:   }
222:   ctx.restore();
223: }
224: function dim(a){ctx.globalAlpha=a;ctx.fillStyle=BG;ctx.fillRect(0,0,LW,H);ctx.globalAlpha=1;}
225: 
226: function draw(){
227:   ctx.setTransform(dpr,0,0,dpr,0,0);
228:   ctx.fillStyle=BG;ctx.fillRect(0,0,cv.width/dpr,cv.height/dpr);
229:   ctx.setTransform(dpr*sc,0,0,dpr*sc,dpr*ox,0);
230:   ctx.save();
231:   ctx.beginPath();ctx.rect(0,0,LW,H);ctx.clip();
232:   if(shake>0)ctx.translate((Math.random()-.5)*16*shake/.35,(Math.random()-.5)*16*shake/.35);
233: 
234:   ctx.fillStyle=MINT;
235:   for(const s of stars){ctx.globalAlpha=.25;ctx.fillRect(s.x,s.y,s.s,s.s);}
236:   ctx.globalAlpha=1;
237: 
238:   const target=rings.find(q=>q.st===0);
239:   for(const r of rings)drawRing(r,r===target&&state!=='over');
240:   if(state!=='over')drawBall();
241:   for(const p of parts){
242:     ctx.globalAlpha=Math.max(0,p.l);ctx.fillStyle=p.c;
243:     ctx.beginPath();ctx.arc(p.x,p.y,3*p.l+.5,0,7);ctx.fill();
244:   }
245:   ctx.globalAlpha=1;
246: 
247:   if(state==='play'||state==='paused'){
248:     txt(String(score),LW/2,98,70*(1+pulse*.18),INK,'center',.9);
249:   }
250:   if(best>0||state==='play')txt('BEST '+best,22,34,14,INK,'left',.6);
251:   drawMute();
252: 
253:   if(state==='ready'){
254:     txt('RING RISE',LW/2,H*.37,54,MINT);
255:     txt('Tap to reverse the glowing ring\u2019s spin',LW/2,H*.37+48,16,INK,'center',.85);
256:     txt('Line up the gaps and rise through!',LW/2,H*.37+72,16,INK,'center',.85);
257:     txt('TAP TO START',LW/2,H*.9,22,GOLD,'center',.55+.45*Math.sin(t*4));
258:   }else if(state==='paused'){
259:     dim(.75);
260:     txt('PAUSED',LW/2,H*.4,44,INK);
261:     txt('TAP TO RESUME',LW/2,H*.4+50,18,GOLD);
262:   }else if(state==='over'){
263:     dim(.8);
264:     txt('GAME OVER',LW/2,H*.24,38,PINK);
265:     txt('SCORE',LW/2,H*.33,16,INK,'center',.7);
266:     txt(String(score),LW/2,H*.4,96,GOLD);
267:     if(newBest)txt('NEW BEST!',LW/2,H*.49,22,PINK);
268:     else txt('BEST '+best,LW/2,H*.49,20,INK,'center',.8);
269:     const ready=performance.now()-overAt>450;
270:     ctx.globalAlpha=ready?1:.45;
271:     ctx.fillStyle=MINT;rr(LW/2-130,H*.57,260,80,24);ctx.fill();
272:     ctx.globalAlpha=1;
273:     txt('PLAY AGAIN',LW/2,H*.57+40,28,BG);
274:   }
275:   ctx.restore();
276: }
277: 
278: /* ---------- loop ---------- */
279: function frame(now){
280:   let dt=(now-last)/1000;last=now;
281:   if(!(dt>0))dt=0;if(dt>.05)dt=.05;
282:   update(dt);draw();
283:   requestAnimationFrame(frame);
284: }
285: resize();
286: last=performance.now();
287: requestAnimationFrame(frame);
288: })();
289: </script>
290: </body>
291: </html>
